/*!
 * \file   test-no-runtime-checks.cxx
 * \brief  This file tests a material property generated by the
 * `generic-parallel` interface with the runtime checks disabled
 * (`disable_runtime_checks` DSL option), with the backend given by the
 * `MFRONT_GPMP_TEST_BACKEND` macro (`stlpar` by default). The memory
 * holding the data, the queue and the synchronization are selected as for
 * the comparisons (see `runtime.hxx`): this file is compiled by the
 * compiler of the backend (for instance `nvcc -x cu` for
 * the `cuda` backend).
 * \date   08/10/2026
 */

#include <array>
#include <cmath>
#include <vector>
#include <iostream>
#include <algorithm>

#include "TFEL/Tests/TestCase.hxx"
#include "TFEL/Tests/TestProxy.hxx"
#include "TFEL/Tests/TestManager.hxx"

#include "runtime.hxx"
#include "MFront/GenericMaterialProperty/MaterialProperty.h"

#ifndef MFRONT_GPMP_TEST_BACKEND
#define MFRONT_GPMP_TEST_BACKEND stlpar
#endif /* MFRONT_GPMP_TEST_BACKEND */
#define MFRONT_GPMP_TEST_STRINGIFY2(x) #x
#define MFRONT_GPMP_TEST_STRINGIFY(x) MFRONT_GPMP_TEST_STRINGIFY2(x)
// clang-format off: the spaces would appear in the name of the header
#define MFRONT_GPMP_TEST_HEADER(name) \
  MFRONT_GPMP_TEST_STRINGIFY(name-generic-parallel-MFRONT_GPMP_TEST_BACKEND.hxx)
// clang-format on

#include MFRONT_GPMP_TEST_HEADER(Inconel600_YoungModulus)
#include "batch.hxx"

//! \brief allocator of the memory selected by runtime.hxx
template <typename T>
struct RuntimeAllocator {
  using value_type = T;
  RuntimeAllocator() = default;
  template <typename T2>
  RuntimeAllocator(const RuntimeAllocator<T2>&) noexcept {}
  T* allocate(const std::size_t n) { return ::allocate<T>(n); }
  void deallocate(T* const p, const std::size_t) noexcept { ::deallocate(p); }
  template <typename T2>
  bool operator==(const RuntimeAllocator<T2>&) const noexcept {
    return true;
  }
};

//! \brief array of values given to the material property
template <typename T>
using test_vector = std::vector<T, RuntimeAllocator<T>>;

extern "C" {
//! \brief identifier of the execution policy expected by the library
extern const char* Inconel600_YoungModulus_generic_parallel_execution_policy;
}

//! \return the execution of a synchronous evaluation (see `runtime.hxx`)
static TestExecution testExecution() {
  return TestExecution{.policy = executionPolicy()};
}  // end of testExecution

struct NoRuntimeChecksTest : public tfel::tests::TestCase {
  NoRuntimeChecksTest()
      : tfel::tests::TestCase("MFront/MaterialProperty/GenericParallel",
                              "NoRuntimeChecksTest") {
  }  // end of NoRuntimeChecksTest

  tfel::tests::TestResult execute() override {
    this->test1();
    this->test2();
    return this->result;
  }  // end of execute

 private:
  [[nodiscard]] static double fct(const double TK) noexcept {
    const double TC = TK - 273.15;
    return (-3.1636e-3 * TC * TC - 3.8654 * TC + 2.1421e+4) * 1e7;
  }  // end of fct

  void test1() {
    // the second temperature is out of its physical bounds, which are not
    // checked: the result is computed at all points, the statuses of the
    // points are null and the statistics given by the calling code are not
    // updated. As with the `generic` interface, the number of arguments
    // is not checked.
    constexpr auto eps = double{1e-2};
    const auto T = test_vector<double>{300, -1, 500, 800};
    auto E = test_vector<double>(4);
    auto statuses = test_vector<int>(4, 12);
    const auto args = std::array<const double*, 1u>{T.data()};
    const auto policy = mfront_gmp_OutOfBoundsPolicy{};
    auto statistics = test_vector<mfront_gpmp_Statistics>(1);
    mfront_gpmp_initializeStatistics(statistics.data());
    auto output = mfront_gpmp_OutputStatus{};
    const auto f = Inconel600_YoungModulus_generic_parallel;
    TFEL_TESTS_CHECK_EQUAL(
        evaluate(f, output, E.data(), 1, args, contiguous<1>(), 4, policy,
                 testExecution(), statuses.data(), 3),
        0);
    TFEL_TESTS_CHECK_EQUAL(output.status, 0);
    TFEL_TESTS_CHECK_EQUAL(output.number_of_failures, mfront_gmp_size_type{0});
    for (std::size_t i = 0; i != E.size(); ++i) {
      TFEL_TESTS_ASSERT(std::abs(E[i] - fct(T[i])) < eps);
      TFEL_TESTS_CHECK_EQUAL(statuses[i], 0);
    }
    // asynchronous evaluation: the result is given once the computations
    // are completed
    std::fill(E.begin(), E.end(), 0.);
    const auto asynchronous = makeExecutionPolicy(
        Inconel600_YoungModulus_generic_parallel_execution_policy,
        {.asynchronous = true});
    TFEL_TESTS_CHECK_EQUAL(
        evaluate(f, output, E.data(), 1, args, contiguous<1>(), 4, policy,
                 TestExecution{.statistics = statistics.data(),
                               .policy = asynchronous.get()}),
        0);
    synchronize();
    for (std::size_t i = 0; i != E.size(); ++i) {
      TFEL_TESTS_ASSERT(std::abs(E[i] - fct(T[i])) < eps);
    }
    TFEL_TESTS_CHECK_EQUAL(statistics[0].number_of_failures, 0ull);
    TFEL_TESTS_CHECK_EQUAL(statistics[0].number_of_unreliable_results, 0ull);
    TFEL_TESTS_CHECK_EQUAL(Inconel600_YoungModulus_generic_parallel_report(
                               &output, statistics.data()),
                           0);
  }

  void test2() {
    // an empty set of points is accepted, the arrays being null
    const auto args = std::array<const double*, 1u>{nullptr};
    auto output = mfront_gpmp_OutputStatus{};
    const auto f = Inconel600_YoungModulus_generic_parallel;
    TFEL_TESTS_CHECK_EQUAL(
        evaluate(f, output, nullptr, 1, args, contiguous<1>(), 0,
                 mfront_gmp_OutOfBoundsPolicy{}, testExecution()),
        0);
    TFEL_TESTS_CHECK_EQUAL(output.status, 0);
    // the checks of the structure of the batch remain
    TFEL_TESTS_CHECK_EQUAL(
        evaluate(f, output, nullptr, 1, args, contiguous<1>(), 4,
                 mfront_gmp_OutOfBoundsPolicy{}, testExecution()),
        -5);
    TFEL_TESTS_CHECK_EQUAL(std::string(output.msg), "no output values given");
    TFEL_TESTS_CHECK_EQUAL(
        Inconel600_YoungModulus_generic_parallel_report(&output, nullptr), -5);
  }
};

TFEL_TESTS_GENERATE_PROXY(NoRuntimeChecksTest, "NoRuntimeChecksTest");

/* coverity [UNCAUGHT_EXCEPT]*/
int main(const int argc, const char* const* argv) {
  if (argc != 2) {
    std::cerr << "no test name given on the command line (argc: " << argc
              << ")";
    return EXIT_FAILURE;
  }
  [[maybe_unused]] const auto runtime = Runtime{};
  auto& m = tfel::tests::TestManager::getTestManager();
  m.addTestOutput(std::cout);
  m.addXMLTestOutput(std::string{argv[1]} + ".xml");
  return m.execute().success() ? EXIT_SUCCESS : EXIT_FAILURE;
}  // end of main
